// QR for https://thepeerscollective.com (29×29, level M), generated once with python-qrcode
const BITS =
  '';
const N = 29;

export default function Qr({ label }: { label: string }) {
  let d = '';
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) if (BITS[y * N + x] === '1') d += `M${x} ${y}h1v1h-1z`;
  return (
    <a className="qr" href="https://thepeerscollective.com" target="_blank" rel="noopener" aria-label={label}>
      <svg viewBox={`0 0 ${N} ${N}`} shapeRendering="crispEdges" aria-hidden>
        <path d={d} fill="#131414" />
      </svg>
    </a>
  );
}
